import type { ComponentStyleVariantConfig, Theme } from "@types";
import type { AvatarProps } from "./avatar.types";
import type { CSSObject } from "@emotion/react";

import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";

// Make sure component name matches its type in the ThemeComponentVariants
const componentName = "Avatar";

export const AvatarClasses = {
  root: "exp-textura_avatar",
  image: "exp-textura_avatar_image",
  ring: "exp-textura_avatar_ring",
  monogram: "exp-textura_avatar_monogram",
  icon: "exp-textura_avatar_icon",
  overflow: "exp-textura_avatar_overflow",
  xxsm: "exp-textura_avatar_xxsm",
  xsm: "exp-textura_avatar_xsm",
  sm: "exp-textura_avatar_sm",
  md: "exp-textura_avatar_md",
  lg: "exp-textura_avatar_lg",
  xlg: "exp-textura_avatar_xlg",
  xxlg: "exp-textura_avatar_xxlg",
};

// Set up style variant settings for the component (if more than "default"), using style slots
const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
  purple: {
    monogram: {
      backgroundColor: theme.avatar.monogram.purple.color.background,
      color: theme.avatar.monogram.purple.color.content,
    },
  },
  blue: {
    monogram: {
      backgroundColor: theme.avatar.monogram.blue.color.background,
      color: theme.avatar.monogram.blue.color.content,
    },
  },
});

// Generate the styles based on the component's props
const generateStyles = (props: AvatarProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<AvatarProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        getVariantConfig(theme),
      ),
    [theme, variant, styleSlotsProp],
  );

  return {
    position: "relative",
    display: "block",
    padding: 0,
    margin: 0,
    overflow: "hidden",
    backgroundColor: theme.color.background.actionEnabled,
    color: theme.color.content.default,
    fontFamily: theme.typography.fontFamily.plusJakartaSans,
    fontWeight: theme.typography.fontWeight[600],
    fontSize: theme.typography.fontSize[16],
    letterSpacing: theme.typography.letterSpacing[0],
    borderRadius: theme.toRem(theme.border.radius.lg),

    [`&.${AvatarClasses.xxsm}`]: {
      width: theme.toRem(16),
      height: theme.toRem(16),
      // TODO: switch this to the micro font of 8 when tokens exists
      fontSize: 8,
      ...styleSlots?.xxsm,
    },
    [`&.${AvatarClasses.xsm}`]: {
      width: theme.toRem(24),
      height: theme.toRem(24),
      fontSize: theme.typography.fontSize[12],
      ...styleSlots?.xsm,
    },
    [`&.${AvatarClasses.sm}`]: {
      width: theme.toRem(28),
      height: theme.toRem(28),
      fontSize: theme.typography.fontSize[12],
      ...styleSlots?.sm,
    },
    [`&.${AvatarClasses.md}`]: {
      width: theme.toRem(32),
      height: theme.toRem(32),
      fontSize: theme.typography.fontSize[12],
      ...styleSlots?.md,
    },
    [`&.${AvatarClasses.lg}`]: {
      width: theme.toRem(40),
      height: theme.toRem(40),
      fontSize: theme.typography.fontSize[16],
      ...styleSlots?.lg,
    },
    [`&.${AvatarClasses.xlg}`]: {
      width: theme.toRem(48),
      height: theme.toRem(48),
      fontSize: theme.typography.fontSize[20],
      ...styleSlots?.xlg,
    },
    [`&.${AvatarClasses.xxlg}`]: {
      width: theme.toRem(60),
      height: theme.toRem(60),
      fontSize: theme.typography.fontSize[24],
      ...styleSlots?.xxlg,
    },

    "&[disabled]": {
      cursor: "not-allowed",
      ...styleSlots?.disabled,
    },

    "&:hover:not(:disabled)": {
      ...styleSlots?.hover,
    },

    "&:focus-visible": {
      ...styleSlots?.focus,
    },

    [`&:focus-visible:not(.${AvatarClasses.ring})`]: {
      outline: "none",
    },

    [`.${AvatarClasses.image}`]: {
      position: "absolute",
      top: 0,
      left: 0,
      display: "block",
      height: "100%",
      width: "100%",
      backgroundPosition: "center",
      backgroundRepeat: "no-repeat",
      ...styleSlots?.image,
    },

    [`.${AvatarClasses.monogram}`]: {
      display: "flex",
      justifyContent: "center",
      alignItems: "center",
      height: "100%",
      width: "100%",
      backgroundColor: theme.avatar.monogram.pink.color.background,
      color: theme.avatar.monogram.pink.color.content,

      [`&.${AvatarClasses.icon}`]: {
        backgroundColor: theme.avatar.icon.color.background,
        color: theme.avatar.icon.color.content,
        ...styleSlots?.icon,
      },

      [`&.${AvatarClasses.overflow}`]: {
        backgroundColor: theme.avatar.overflow.color.background,
        color: theme.avatar.overflow.color.content,
        ...styleSlots?.overflow,
      },

      ...styleSlots?.monogram,
    },

    [`&.${AvatarClasses.ring}`]: {
      outlineStyle: "solid",
      outlineWidth: theme.toRem(theme.border.width.sm),
      outlineOffset: "0px",
      ...styleSlots?.ring,
    },

    ...styleSlots?.root,
  };
};

// Exclude props from the DOM element
const excludedDOMProps = getExcludedDOMProps();

// Styled component for Avatar, excludes invalid props
export const StyledAvatar = styled("div", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<AvatarProps>((props) => generateStyles(props));
